	"sdk/component-ui/cn.ts": "// Package-owned class-name helper for component-ui primitives. Mirrors the\n// shadcn-vue `cn` utility so package primitives never reach into the host app's\n// `@/lib/utils`.\n\nimport type { ClassValue } from \"clsx\";\nimport { clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n",
	"sdk/component-ui/collapsible/Collapsible.vue": "<script setup lang=\"ts\">\nimport type { CollapsibleRootEmits, CollapsibleRootProps } from \"reka-ui\";\nimport { CollapsibleRoot, useForwardPropsEmits } from \"reka-ui\";\n\nconst props = defineProps<CollapsibleRootProps>();\nconst emits = defineEmits<CollapsibleRootEmits>();\n\nconst forwarded = useForwardPropsEmits(props, emits);\n<\/script>\n\n<template>\n  <CollapsibleRoot v-slot=\"slotProps\" data-slot=\"collapsible\" v-bind=\"forwarded\">\n    <slot v-bind=\"slotProps\" />\n  </CollapsibleRoot>\n</template>\n",
