	"sdk/component-ui/dropdown-menu/DropdownMenuCheckboxItem.vue": "<script setup lang=\"ts\">\nimport type { DropdownMenuCheckboxItemEmits, DropdownMenuCheckboxItemProps } from \"reka-ui\";\n\nimport type { HTMLAttributes } from \"vue\";\nimport { reactiveOmit } from \"@vueuse/core\";\nimport { CheckIcon } from \"lucide-vue-next\";\nimport { DropdownMenuCheckboxItem, DropdownMenuItemIndicator, useForwardPropsEmits } from \"reka-ui\";\nimport { cn } from \"../cn\";\n\nconst props = defineProps<DropdownMenuCheckboxItemProps & { class?: HTMLAttributes[\"class\"] }>();\nconst emits = defineEmits<DropdownMenuCheckboxItemEmits>();\n\nconst delegatedProps = reactiveOmit(props, \"class\");\n\nconst forwarded = useForwardPropsEmits(delegatedProps, emits);\n<\/script>\n\n<template>\n  <DropdownMenuCheckboxItem\n    data-slot=\"dropdown-menu-checkbox-item\"\n    v-bind=\"forwarded\"\n    :class=\"\n      cn(\n        'focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground gap-1.5 rounded-md py-1 pr-8 pl-1.5 text-sm data-inset:pl-7 [&_svg:not([class*=size-])]:size-4 relative flex cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0',\n        props.class,\n      )\n    \"\n  >\n    <span\n      class=\"absolute right-2 flex items-center justify-center pointer-events-none\"\n      data-slot=\"dropdown-menu-checkbox-item-indicator\"\n    >\n      <DropdownMenuItemIndicator>\n        <slot name=\"indicator-icon\">\n          <CheckIcon />\n        </slot>\n      </DropdownMenuItemIndicator>\n    </span>\n    <slot />\n  </DropdownMenuCheckboxItem>\n</template>\n",
	"sdk/component-ui/dropdown-menu/DropdownMenuContent.vue": "<script setup lang=\"ts\">\nimport type { DropdownMenuContentEmits, DropdownMenuContentProps } from \"reka-ui\";\nimport type { HTMLAttributes } from \"vue\";\nimport { reactiveOmit } from \"@vueuse/core\";\nimport { DropdownMenuContent, DropdownMenuPortal, useForwardPropsEmits } from \"reka-ui\";\nimport { cn } from \"../cn\";\n\ndefineOptions({\n  inheritAttrs: false,\n});\n\nconst props = withDefaults(\n  defineProps<\n    DropdownMenuContentProps & { class?: HTMLAttributes[\"class\"]; disablePortal?: boolean }\n  >(),\n  {\n    align: \"start\",\n    sideOffset: 4,\n    disablePortal: false,\n  },\n);\nconst emits = defineEmits<DropdownMenuContentEmits>();\n\nconst delegatedProps = reactiveOmit(props, \"class\", \"disablePortal\");\n\nconst forwarded = useForwardPropsEmits(delegatedProps, emits);\n<\/script>\n\n<template>\n  <DropdownMenuPortal :disabled=\"props.disablePortal\">\n    <DropdownMenuContent\n      data-slot=\"dropdown-menu-content\"\n      v-bind=\"{ ...$attrs, ...forwarded }\"\n      :class=\"\n        cn(\n          'data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground min-w-32 rounded-lg p-1 shadow-md ring-1 duration-100 cn-menu-translucent z-50 max-h-(--reka-dropdown-menu-content-available-height) w-(--reka-dropdown-menu-trigger-width) origin-(--reka-dropdown-menu-content-transform-origin) overflow-x-hidden overflow-y-auto data-[state=closed]:overflow-hidden',\n          props.class,\n        )\n      \"\n    >\n      <slot />\n    </DropdownMenuContent>\n  </DropdownMenuPortal>\n</template>\n",
	"sdk/component-ui/dropdown-menu/DropdownMenuTrigger.vue": "<script setup lang=\"ts\">\nimport type { DropdownMenuTriggerProps } from \"reka-ui\";\nimport { DropdownMenuTrigger, useForwardProps } from \"reka-ui\";\n\nconst props = defineProps<DropdownMenuTriggerProps>();\n\nconst forwardedProps = useForwardProps(props);\n<\/script>\n\n<template>\n  <DropdownMenuTrigger data-slot=\"dropdown-menu-trigger\" v-bind=\"forwardedProps\">\n    <slot />\n  </DropdownMenuTrigger>\n</template>\n",
